-- =====================================================================
-- ShareWood — offres issues de sources publiques, récupérées le 2026-11-28 par scripts/import_sources.mjs.
-- 45 offres. NE PAS MODIFIER À LA MAIN : relancer le script.
-- Prérequis : migration 024_deal_source.sql. À coller dans Supabase → SQL Editor → Run.
-- À relancer après reset_demo.sql (qui efface le compte « Sources publiques »).
-- Relançable : remplace les offres importées auparavant (et leurs réactions).
-- Sources : OpenAgenda (Licence Ouverte), Aides Jeunes (Licence Ouverte).
-- =====================================================================
do $import$
declare
  bot uuid;
  bot_email constant text := 'sources@example.com';
begin
  if not exists (select 1 from information_schema.columns
                  where table_schema = 'public' and table_name = 'deals' and column_name = 'source_name') then
    raise exception 'Lance d''abord supabase/migrations/024_deal_source.sql.';
  end if;

  -- Compte technique, auteur des offres importées : mot de passe aléatoire jamais communiqué.
  select id into bot from auth.users where email = bot_email;
  if bot is null then
    bot := gen_random_uuid();
    insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
      confirmation_token, email_change, email_change_token_new, recovery_token)
    values ('00000000-0000-0000-0000-000000000000', bot, 'authenticated', 'authenticated', bot_email,
      extensions.crypt(gen_random_uuid()::text, extensions.gen_salt('bf')), now(),
      '{"provider":"email","providers":["email"]}', '{"username":"Sources publiques"}', now(), now(), '', '', '', '');
  end if;

  delete from public.deals where author_id = bot;

  insert into public.deals (title, description, category, subcategory, scope, zone_id, place_name, lat, lng,
    price_level, tags, requirements, expires_at, link_url, source_name, source_checked_at, author_id, created_at)
  select v.title, v.description, v.category::deal_category, v.subcategory::deal_subcategory, v.scope::deal_scope,
    v.zone_id, v.place_name, v.lat::double precision, v.lng::double precision, v.price_level::int, v.tags,
    v.requirements, v.expires_at::timestamptz, v.link_url, v.source_name, date '2026-11-28', bot,
    now() - make_interval(mins => 30 + v.rank * 7)
  from (values
    ('Concert gratuit : Ledeunff', 'Une afro vissée sur la tête et une voix unique, à la fois rocailleuse et lumineuse, Ledeunff propose une musique à son image, qu’il définit «d’acoustic black music». Mardi 15 décembre, 20h30. Tarif : Gratuit, sans réservation.', 'activity', null, 'local', 'bruz', 'Le Grand Logis · Bruz', 48.023141, -1.744908, 0, array['music']::text[], array[]::text[], '2026-12-15T21:00:00+00:00', 'https://openagenda.com/sortir-rennesmetropole/events/concert-gratuit-ledeunff', 'OpenAgenda', 0),
    ('Salon de l’Étudiant - Rennes', 'Le salon du lycéen et de l’étudiant de la région académique Bretagne. 8 et 9 janvier 2027. Tarif : Gratuit.', 'activity', null, 'local', 'ker-lann', 'Parc des expositions de Rennes · Bruz', 48.059496, -1.734295, 0, array['culture']::text[], array[]::text[], '2027-01-09T17:00:00+00:00', 'https://openagenda.com/echosciences/events/salon-de-letudiant-rennes-4527000', 'OpenAgenda', 1),
    ('OPEN LAB MQB', 'Découpeuse laser, impression 3D, réalisation et montage vidéo…Espace de création et lieu de ressources, l’Espace public numérique vous propose un temps consacré à la création et fabrication numérique. 9 janvier 2025 - 29 août 2030, les jeudis. Tarif : Utilisation des machines gratuites, mais venez avec votre matériel.', 'activity', null, 'local', 'rennes', 'Maison de quartier La Bellangerais · Rennes', 48.135572, -1.668065, 0, array['culture']::text[], array[]::text[], '2030-08-29T18:00:00+00:00', 'https://openagenda.com/sortir-rennesmetropole/events/open-lab-mqb', 'OpenAgenda', 2),
    ('Une Histoire de Bretagne, de la Préhistoire à la Révolution.', 'De l''installation des premiers groupes humains à la Préhistoire jusqu''à la Révolution française, la Bretagne n’a cessé de se transformer. 2 septembre 2025 - 31 août 2028. Tarif : Gratuit.', 'activity', null, 'local', 'rennes', 'Musée de Bretagne · Rennes', 48.105139, -1.674686, 0, array['culture']::text[], array[]::text[], '2028-08-31T17:00:00+00:00', 'https://openagenda.com/agenda-monumentaire/events/une-histoire-de-bretagne-4126205', 'OpenAgenda', 3),
