    ('Bourse sur critères sociaux', 'La bourse d''enseignement supérieur sur critères sociaux (BCS) est accordée aux étudiants et étudiantes qui ont des difficultés matérielles pour poursuivre des études supérieures. Proposé par : L’État français. Conditions et montants sur la page officielle.', 'scholarship', null, 'national', null, null, null, null, null, array[]::text[], array[]::text[], null, 'https://www.service-public.fr/particuliers/vosdroits/F12214', 'Aides Jeunes (1jeune1solution)', 30),
    ('Aide à la mobilité internationale', 'L’Aide à la Mobilité Internationale (AMI) est une bourse destinée aux étudiants boursiers sur critères sociaux ou bénéficiant d’une aide spécifique annuelle. Elle soutient les séjours d’études ou de stage à l’étranger, d’une durée comprise entre 1 et 10 mois consécutifs, dans le cadre du cursus universitaire. Elle est… Proposé par : L’État français. Conditions et montants sur la page officielle.', 'scholarship', null, 'national', null, null, null, null, null, array[]::text[], array['scholarship']::text[], null, 'https://www.etudiant.gouv.fr/fr/bourses-erasmus-et-aide-la-mobilite-internationale-ami-67', 'Aides Jeunes (1jeune1solution)', 31),
    ('Aide au mérite', 'L''aide au mérite concerne les étudiants ayant reçu une mention "très bien" durant la dernière session du baccalauréat. Proposé par : L’État français. Conditions et montants sur la page officielle.', 'scholarship', null, 'national', null, null, null, null, null, array[]::text[], array['scholarship']::text[], null, 'https://www.etudiant.gouv.fr/fr/aide-au-merite-1291', 'Aides Jeunes (1jeune1solution)', 32),
    ('Aide à la mobilité Master', 'Cette aide facilite la mobilité géographique des étudiants titulaires d’un diplôme national de licence qui s’inscrivent pour la première fois en première année de diplôme national de master qui fait suite à l’année d’obtention de la licence dans une région académique différente. Proposé par : L’État français. Conditions et montants sur la page officielle.', 'scholarship', null, 'national', null, null, null, null, null, array[]::text[], array[]::text[], null, 'https://www.service-public.fr/particuliers/vosdroits/F34343', 'Aides Jeunes (1jeune1solution)', 33),
    ('Repas du CROUS pour les étudiants', 'Les restaurants universitaires du CROUS délivrent des repas à 1 euro pour les étudiants. Proposé par : L’État français. Conditions et montants sur la page officielle.', 'restaurant', null, 'national', null, null, null, null, null, array[]::text[], array[]::text[], null, 'https://www.lescrous.fr/repas-a-1-euro-foire-aux-questions/', 'Aides Jeunes (1jeune1solution)', 34),
    ('Logement dans une résidence universitaire du CROUS', 'Les logements gérés par le Crous sont destinés aux étudiants dont les familles disposent de faibles ressources. Plusieurs types de logement peuvent être proposés en fonction des résidences. Regarder le tutoriel vidéo de demande de logement Crous (Dailymotion) . Proposé par : L’État français. Conditions et montants sur la page officielle.', 'scholarship', null, 'national', null, null, null, null, null, array[]::text[], array[]::text[], null, 'https://www.etudiant.gouv.fr/fr/bourse-et-logement-constituez-votre-dossier-social-etudiant-dse-409#item4', 'Aides Jeunes (1jeune1solution)', 35),
    ('Résidences à loyer modéré pour les étudiants, stagiaires et apprentis', 'Certains bailleurs sociaux et associations proposent des logements étudiants à loyer modéré : studios, T2 ou colocations meublées, souvent situés près des campus. Ces résidences sont destinées aux étudiants, apprentis et stagiaires aux revenus modestes et peuvent donner droit aux aides au logement. La demande se fait… Proposé par : L’État français. Conditions et montants sur la page officielle.', 'scholarship', null, 'national', null, null, null, null, null, array[]::text[], array[]::text[], null, 'https://monlogementetudiant.beta.gouv.fr/?utm_source=mes-aides&utm_medium=referral&utm_campaign=residences-etudiantes&utm_content=plus-d-informations', 'Aides Jeunes (1jeune1solution)', 36),
    ('Colocations solidaires pour les étudiants', 'Les colocations solidaires offrent un logement à loyer modéré en échange d''un engagement au service de la collectivité, que ce soit dans une résidence, un quartier ou auprès de personnes âgées. Au service d''une cause&nbsp;:&nbsp; AFEV ,&nbsp; CoopColoc &nbsp; MaisonArticle1 . Cohabitation intergénérationnelle&nbsp;:&nbsp;… Proposé par : L’État français. Conditions et montants sur la page officielle.', 'scholarship', null, 'national', null, null, null, null, null, array[]::text[], array[]::text[], null, 'https://www.etudiant.gouv.fr/fr/les-colocations-solidaires-358', 'Aides Jeunes (1jeune1solution)', 37),
    ('Aide à l’alimentation pour les étudiants éloignés des restaurants universitaires', 'Cette aide financière soutient les étudiants qui n’ont pas accès facilement aux restaurants universitaires. Les établissements d’enseignement supérieur situés dans des zones sans restaurant universitaire ou conventionné transmettront la liste des étudiants éligibles aux Crous. Les bénéficiaires recevront une carte prépayée… Proposé par : L’État français. Conditions et montants sur la page officielle.', 'scholarship', null, 'national', null, null, null, null, null, array[]::text[], array[]::text[], null, 'https://www.1jeune1solution.gouv.fr/articles/aide-financiere-etudiants-restauration-universitaire', 'Aides Jeunes (1jeune1solution)', 38),
    ('Prêt étudiant garanti par l''État', 'Le prêt étudiant est ouvert à l''ensemble des étudiants sans conditions de ressources et sans caution parentale ou d''un tiers. Vous avez la possibilité de commencer à rembourser l''emprunt de manière différée, quand vous aurez terminé vos études et trouvé un travail. Proposé par : L’État français. Conditions et montants sur la page officielle.', 'scholarship', null, 'national', null, null, null, null, null, array[]::text[], array[]::text[], null, 'https://www.etudiant.gouv.fr/fr/pret-etudiant-garanti-par-l-etat-1723', 'Aides Jeunes (1jeune1solution)', 39),
    ('Santé Psy Étudiant', 'Vous êtes étudiant ou étudiante et vous ressentez le besoin d’une aide psychologique ? Vous pouvez bénéficier de 12 séances gratuites avec un psychologue partenaire, sans avance de frais. Proposé par : L’État français. Conditions et montants sur la page officielle.', 'scholarship', null, 'national', null, null, null, null, null, array[]::text[], array[]::text[], null, 'https://santepsy.etudiant.gouv.fr/', 'Aides Jeunes (1jeune1solution)', 40),
    ('Carte SNCF élèves, étudiants et apprentis', 'Vous êtes élève de moins de 21 ans, étudiant de moins de 26 ans ou apprenti de moins de 23 ans, la SNCF vous propose une carte d''abonnement qui vous permet de voyager à votre gré et à moindre coût entre votre domicile et votre lieu d''études ou d''apprentissage, en TGV INOUI et INTERCITES. Proposé par : SNCF. Conditions et montants sur la page officielle.', 'transport', 'train', 'national', null, null, null, null, null, array[]::text[], array[]::text[], null, 'https://www.sncf-voyageurs.com/fr/voyagez-avec-nous/en-france/tarifs-grandes-lignes/eleves-etudiants-et-apprentis/', 'Aides Jeunes (1jeune1solution)', 41),
    ('Bretagne : Abonnement BreizhGo', 'Les abonnements BreizhGo -26 ans TER options TGV et réseaux urbains vous permettent d''emprunter en illimité les TER, TGV et bus, métro ou tram sur un trajet donné. Proposé par : Bretagne. Conditions et montants sur la page officielle.', 'transport', 'train', 'national', null, null, null, null, null, array[]::text[], array[]::text[], null, 'https://www.ter.sncf.com/bretagne/abonnements/tous-les-abonnements/abonnements-ter-tgv-reseaux-urbains', 'Aides Jeunes (1jeune1solution)', 42),
    ('Bretagne : Bourse « Jeunes à l’international » n°4 – étudiants et étudiantes des…', 'La région Bretagne finance les étudiants et étudiantes des universités ou en 3ème année de BUT dans leur projet de stage professionnel ou de séjour d’études à l’étranger. Proposé par : Bretagne. Conditions et montants sur la page officielle.', 'scholarship', null, 'national', null, null, null, null, null, array[]::text[], array[]::text[], null, 'https://www.bretagne.bzh/actualites/bougez-en-europe-et-dans-le-monde/', 'Aides Jeunes (1jeune1solution)', 43),
    ('Bretagne : Bourse B-Monde Mobilité individuelle', 'La région Bretagne encourage la mobilité internationale des lycéens, étudiants et stagiaires de la formation professionnelle, en leur offrant des bourses pour les aider à financer un stage ou un séjour d’études à l’étranger, réalisé dans le cadre du cursus de formation et faisant l’objet d’une validation par l’établissement… Proposé par : Bretagne. Conditions et montants sur la page officielle.', 'scholarship', null, 'national', null, null, null, null, null, array[]::text[], array[]::text[], null, 'https://europe.bzh/aides/fiches/b-monde-mobilite-individuelle/', 'Aides Jeunes (1jeune1solution)', 44)
